typedef struct ls_iter_t {
        void *data;
        struct ls_iter_t *n, *p;
} SdbListIter;

typedef struct ls_t {
        size_t length;
        SdbListIter *head;
        SdbListIter *tail;
        SdbListFree free;
        SdbListComparator cmp;
